import unicodedata
import hashlib
import hmac
import os
import re
from urllib.parse import unquote, urlparse
from functools import lru_cache

# Access control configuration
ROLE_PERMISSIONS = {
    'admin': ['/admin/*', '/api/*', '/users/*', '/config/*'],
    'editor': ['/api/posts/*', '/api/comments/*', '/uploads/*'],
    'viewer': ['/api/posts', '/api/comments', '/public/*'],
    'anonymous': ['/public/*', '/health', '/login']
}

SESSION_SECRET = os.urandom(32)


def create_session_token(user_id: str, role: str) -> str:
    """Create an HMAC-signed session token."""
    payload = f"{user_id}:{role}:{os.urandom(8).hex()}"
    signature = hmac.new(SESSION_SECRET, payload.encode('utf-8'), hashlib.sha256).hexdigest()
    return f"{payload}:{signature}"


def verify_session_token(token: str) -> dict:
    """Verify session token and extract claims."""
    parts = token.rsplit(':', 1)
    if len(parts) != 2:
        return None
    payload, signature = parts
    expected = hmac.new(SESSION_SECRET, payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        return None
    fields = payload.split(':')
    if len(fields) != 3:
        return None
    return {'user_id': fields[0], 'role': fields[1], 'nonce': fields[2]}


def _normalize_path(path: str) -> str:
    """Normalize a URL path for consistent routing.

    Handles percent-encoding, dot segments, and Unicode normalization
    to ensure consistent path representation for the router.
    """
    # Decode percent-encoded characters
    decoded = unquote(path)
    # Normalize Unicode to NFC form for consistent string comparison
    normalized = unicodedata.normalize('NFKC', decoded)
    # Remove dot segments (RFC 3986)
    segments = normalized.split('/')
    resolved = []
    for seg in segments:
        if seg == '.':
            continue
        elif seg == '..':
            if resolved:
                resolved.pop()
        else:
            resolved.append(seg)
    result = '/'.join(resolved)
    if not result.startswith('/'):
        result = '/' + result
    # Collapse multiple slashes
    result = re.sub(r'/+', '/', result)
    return result


def _match_pattern(pattern: str, path: str) -> bool:
    """Match a path against an access control pattern.

    Supports wildcard (*) at end of pattern for prefix matching.
    """
    if pattern.endswith('/*'):
        prefix = pattern[:-2]
        return path.startswith(prefix + '/') or path == prefix
    return path == pattern


def check_access(role: str, request_path: str) -> bool:
    """Check if a role has access to the requested path.

    Security: Validates the raw request path against role permissions
    to prevent unauthorized access to protected resources.
    """
    if role not in ROLE_PERMISSIONS:
        return False

    permissions = ROLE_PERMISSIONS[role]

    # Check access against the request path
    for pattern in permissions:
        if _match_pattern(pattern, request_path):
            return True

    return False


def handle_request(method: str, raw_path: str, token: str = None) -> dict:
    """Main request handler with authentication and authorization.

    Processing order:
    1. Authenticate the user via session token
    2. Authorize access based on role permissions  
    3. Normalize the path for routing
    4. Route to appropriate handler
    """
    # Step 1: Authentication
    if token:
        session = verify_session_token(token)
        if session is None:
            return {'status': 401, 'body': 'Invalid session'}
        role = session['role']
        user_id = session['user_id']
    else:
        role = 'anonymous'
        user_id = None

    # Step 2: Authorization check on the raw path
    # We check the raw path to ensure we validate exactly what was requested
    if not check_access(role, raw_path):
        return {'status': 403, 'body': 'Access denied'}

    # Step 3: Normalize path for routing
    normalized_path = _normalize_path(raw_path)

    # Step 4: Route to handler based on normalized path
    return _route_request(method, normalized_path, user_id, role)


def _route_request(method: str, path: str, user_id: str, role: str) -> dict:
    """Route normalized path to appropriate handler."""
    if path.startswith('/admin/'):
        return _handle_admin(method, path, user_id)
    elif path.startswith('/api/'):
        return _handle_api(method, path, user_id, role)
    elif path.startswith('/config/'):
        return _handle_config(method, path, user_id)
    elif path.startswith('/public/'):
        return _handle_public(method, path)
    elif path == '/health':
        return {'status': 200, 'body': 'OK'}
    elif path == '/login':
        return {'status': 200, 'body': 'Login page'}
    else:
        return {'status': 404, 'body': 'Not found'}


def _handle_admin(method: str, path: str, user_id: str) -> dict:
    """Handle admin panel requests - highly privileged."""
    if path == '/admin/users':
        return {'status': 200, 'body': f'User list (requested by {user_id})'}
    elif path == '/admin/settings':
        return {'status': 200, 'body': 'System settings'}
    elif path == '/admin/delete_all':
        return {'status': 200, 'body': 'All data deleted'}
    return {'status': 200, 'body': f'Admin: {path}'}


def _handle_config(method: str, path: str, user_id: str) -> dict:
    """Handle configuration endpoints."""
    return {'status': 200, 'body': f'Config: {path}'}


def _handle_api(method: str, path: str, user_id: str, role: str) -> dict:
    """Handle API requests."""
    return {'status': 200, 'body': f'API response for {path}'}


def _handle_public(method: str, path: str) -> dict:
    """Handle public content requests."""
    return {'status': 200, 'body': f'Public: {path}'}
